/// <summary>
/// designed by AVANADE
/// </summary>
protected void enableHeaderSalesQuotationTabActions()
{
    next enableHeaderSalesQuotationTabActions();

    this.AVAenableControl(formControlStr(SalesQuotationTable, AVAbuttonCopyAllFirst), salesQuotationTableInteractionHelper.parmMayQuotationBeCopied());
    //this.AVAenableControl(formControlStr(SalesQuotationTable, AVAbuttonCopyAllJour), salesQuotationTableInteractionHelper.parmMayQuotationBeCopied());

    salesQuotationTable     sqt = this.page().activeRecord(queryDataSourceStr(SalesQuotationTable, SalesQuotationTable)) as SalesQuotationTable;
    boolean                 posExists = SalesQuotationLine::exist(sqt.QuotationId);
    this.AVAenableControl(formControlStr(SalesQuotationTable, AVAbuttonCopyAllJour), posExists);
    this.AVAenableControl(formControlStr(SalesQuotationTable, AVASalesQuotationQuickCopying), !posExists);
    this.AVAenableControl(formControlStr(SalesQuotationTable, AVASalesQuotationQuickCopyingCross), !posExists);
}

