/// <summary>
///    AVA <c>AVAenableControl</c> method.
/// </summary>
/// <param name="_formControlStr">
///    <c>str</c> as type
/// </param>
/// <param name="_enabled">
///    <c>boolean</c> as type
/// </param>
private void AVAenableControl(str _formControlStr, boolean _enabled)
{
    this.page().actionPaneControlEnabled(_formControlStr, _enabled);
}

/// <summary>
/// designed by AVANADE
/// </summary>
protected void enableCommonActions()
{
    next enableCommonActions();
    /*
    this.AVAenableControl(formControlStr(SalesQuotationTable, AVAUpdateQuotation), salesQuotationTableInteractionHelper.parmUpdateQuotationEnabled());
    */
    this.AVAenableControl(formControlStr(SalesQuotationTable, AVAUpdateQuotation), true);
}

/// <summary>
///    AVA <c>enableHeaderQuoteTabActions</c> method.
/// </summary>
protected void enableHeaderQuoteTabActions()
{
    next enableHeaderQuoteTabActions();

    // Journals
    this.page().actionPaneControlEnabled(formControlStr(SalesQuotationTable, AVAButtonJournalQuotationAll), salesQuotationTableInteractionHelper.parmJournalQuotationEnabled());

    // Accounts
    this.page().actionPaneControlVisible(formControlStr(SalesQuotationTable, AVACustomer), true);
    this.page().actionPaneControlEnabled(formControlStr(salesQuotationTable, AVACustomer), !salesQuotationTableInteractionHelper.parmIsProspect());
    this.page().actionPaneControlVisible(formControlStr(SalesQuotationTable, AVABusinessRelationShip), true);
    this.page().actionPaneControlEnabled(formControlStr(salesQuotationTable, AVABusinessRelationShip), salesQuotationTableInteractionHelper.parmIsProspect());
    this.page().actionPaneControlVisible(formControlStr(SalesQuotationTable, AVAContactPerson), true);
    this.page().actionPaneControlEnabled(formControlStr(SalesQuotationTable, AVAContactPerson), salesQuotationTableInteractionHelper.parmIsNotTemplate());
}

/// <summary>
///    Enables or disables the header level general tab menu items.
/// </summary>
protected void enableHeaderGeneralTabActions()
{
    next enableHeaderGeneralTabActions();

    // Related information
    this.page().actionPaneControlVisible(formControlStr(SalesQuotationTable, ButtonAlternativeQuotations), false);
    //this.enableControl(formControlStr(SalesQuotationTable, smmDocuments), salesQuotationTableInteractionHelper.parmIsNotTemplate());
}
